=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none
// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Traces to requirement req-294155bac1; interface per interface_spec.md,
// structure per microarchitecture.md (zero wait states, no state machine).
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

    // ------------------------------------------------------------------
    // Transfer qualification (microarchitecture section 1)
    // ------------------------------------------------------------------
    wire access;
    assign access = psel & penable;

    // ------------------------------------------------------------------
    // Address decode (microarchitecture section 3): word aligned, 0x0..0xC
    // ------------------------------------------------------------------
    wire       mapped;
    wire [1:0] idx;
    assign mapped = (paddr[1:0] == 2'b00) &&
                    (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    assign idx    = paddr[3:2];

    wire wr_en;
    assign wr_en = access & pwrite & mapped;

    wire we0;
    wire we1;
    wire we2;
    wire we3;
    assign we0 = wr_en & (idx == 2'd0);
    assign we1 = wr_en & (idx == 2'd1);
    assign we2 = wr_en & (idx == 2'd2);
    assign we3 = wr_en & (idx == 2'd3);

    // ------------------------------------------------------------------
    // Byte-lane write mask from pstrb (microarchitecture section 2)
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wmask;
    genvar g;
    generate
        for (g = 0; g < DATA_WIDTH/8; g = g + 1) begin : g_lane
            assign wmask[8*g +: 8] = {8{pstrb[g]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register file: four separate registers
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    wire [DATA_WIDTH-1:0] reg0_d;
    wire [DATA_WIDTH-1:0] reg1_d;
    wire [DATA_WIDTH-1:0] reg2_d;
    wire [DATA_WIDTH-1:0] reg3_d;
    assign reg0_d = (reg0 & ~wmask) | (pwdata & wmask);
    assign reg1_d = (reg1 & ~wmask) | (pwdata & wmask);
    assign reg2_d = (reg2 & ~wmask) | (pwdata & wmask);
    assign reg3_d = (reg3 & ~wmask) | (pwdata & wmask);

    // Synchronous, active-low reset (microarchitecture section 5)
    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else begin
            if (we0) reg0 <= reg0_d;
            if (we1) reg1 <= reg1_d;
            if (we2) reg2 <= reg2_d;
            if (we3) reg3 <= reg3_d;
        end
    end

    // ------------------------------------------------------------------
    // Read data (microarchitecture section 4): combinational 4:1 mux,
    // zero unless this is a mapped read access.
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] rd_mux;
    assign rd_mux = (idx == 2'd0) ? reg0 :
                    (idx == 2'd1) ? reg1 :
                    (idx == 2'd2) ? reg2 :
                                    reg3;

    assign prdata  = (access && !pwrite && mapped) ? rd_mux : {DATA_WIDTH{1'b0}};
    assign pslverr = access & ~mapped;
    assign pready  = 1'b1;

`ifdef FORMAL
    // Design-intent assertions (not a full proof; see notes).
    always @(*) begin
        assert(pready == 1'b1);
        if (!access) begin
            assert(prdata == {DATA_WIDTH{1'b0}});
            assert(pslverr == 1'b0);
        end
        if (access && !mapped) begin
            assert(pslverr == 1'b1);
            assert(prdata == {DATA_WIDTH{1'b0}});
        end
        if (access && mapped) begin
            assert(pslverr == 1'b0);
        end
    end
`endif

endmodule
`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns/1ps
`default_nettype none
// Self-checking directed testbench for apb_regs (interface_spec.md section 7).
// Inputs are driven after the falling edge and sampled 1 ns later, well
// before the rising edge, so there is no race with the design.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    integer        passed;
    integer        failed;
    integer        i;
    integer        r;
    integer        s;
    reg [31:0]     model [0:3];
    reg [7:0]      bad_addrs [0:15];
    reg [8*64-1:0] nonce;
    reg            done;

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ---------------- reference model (independent of the RTL) ----------
    function is_mapped_tb;
        input [7:0] a;
        begin
            is_mapped_tb = (a[1:0] == 2'b00) && (a < 8'h10);
        end
    endfunction

    function [31:0] merge_tb;
        input [31:0] old_v;
        input [31:0] new_v;
        input [3:0]  st;
        begin
            merge_tb[7:0]   = st[0] ? new_v[7:0]   : old_v[7:0];
            merge_tb[15:8]  = st[1] ? new_v[15:8]  : old_v[15:8];
            merge_tb[23:16] = st[2] ? new_v[23:16] : old_v[23:16];
            merge_tb[31:24] = st[3] ? new_v[31:24] : old_v[31:24];
        end
    endfunction

    // ---------------- checks ---------------------------------------------
    // Outside the access phase: prdata and pslverr zero; pready always high.
    task check_quiet;
        begin
            #1;
            if (prdata !== 32'h0000_0000) begin
                failed = failed + 1;
                $error("quiet cycle at %0t: prdata=%h, expected 0", $time, prdata);
            end else passed = passed + 1;
            if (pslverr !== 1'b0) begin
                failed = failed + 1;
                $error("quiet cycle at %0t: pslverr=%b, expected 0", $time, pslverr);
            end else passed = passed + 1;
            if (pready !== 1'b1) begin
                failed = failed + 1;
                $error("quiet cycle at %0t: pready=%b, expected 1", $time, pready);
            end else passed = passed + 1;
        end
    endtask

    // In the access phase: zero wait states, response per address policy.
    task check_access;
        input        exp_err;
        input [31:0] exp_data;
        begin
            #1;
            if (pready !== 1'b1) begin
                failed = failed + 1;
                $error("access at %0t addr=%h: pready=%b, expected 1 (zero wait states)", $time, paddr, pready);
            end else passed = passed + 1;
            if (pslverr !== exp_err) begin
                failed = failed + 1;
                $error("access at %0t addr=%h write=%b: pslverr=%b, expected %b", $time, paddr, pwrite, pslverr, exp_err);
            end else passed = passed + 1;
            if (prdata !== exp_data) begin
                failed = failed + 1;
                $error("access at %0t addr=%h write=%b: prdata=%h, expected %h", $time, paddr, pwrite, prdata, exp_data);
            end else passed = passed + 1;
        end
    endtask

    // ---------------- bus tasks ------------------------------------------
    task apb_write;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  st;
        reg          exp_err;
        begin
            exp_err = !is_mapped_tb(a);
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = a;
            pwdata  = d;
            pstrb   = st;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            check_access(exp_err, 32'h0000_0000);
            @(posedge pclk);
            if (!exp_err) model[a[3:2]] = merge_tb(model[a[3:2]], d, st);
        end
    endtask

    task apb_read;
        input [7:0] a;
        reg         exp_err;
        reg [31:0]  exp_d;
        begin
            exp_err = !is_mapped_tb(a);
            exp_d   = exp_err ? 32'h0000_0000 : model[a[3:2]];
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = a;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            check_access(exp_err, exp_d);
            @(posedge pclk);
        end
    endtask

    // Idle cycles with hostile inputs: psel low but a full-strobe write to a
    // mapped address is presented; nothing may change and outputs stay quiet.
    task idle;
        input integer n;
        integer k;
        begin
            for (k = 0; k < n; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b1;
                paddr   = 8'h04;
                pwdata  = 32'hDEAD_BEEF;
                pstrb   = 4'hF;
                check_quiet;
            end
        end
    endtask

    task read_all;
        integer q;
        begin
            for (q = 0; q < 4; q = q + 1)
                apb_read({4'h0, q[1:0], 2'b00});
        end
    endtask

    task finish_run;
        begin
            nonce = {64{8'h00}};
            if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
                nonce = {64{8'h00}};
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    endtask

    // ---------------- watchdog -------------------------------------------
    initial begin
        #1000000;
        if (!done) begin
            failed = failed + 1;
            $error("watchdog: simulation did not complete");
            finish_run;
        end
    end

    // ---------------- directed sequence ----------------------------------
    initial begin
        done     = 1'b0;
        passed   = 0;
        failed   = 0;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;

        bad_addrs[0]  = 8'h01; bad_addrs[1]  = 8'h02;
        bad_addrs[2]  = 8'h03; bad_addrs[3]  = 8'h05;
        bad_addrs[4]  = 8'h06; bad_addrs[5]  = 8'h07;
        bad_addrs[6]  = 8'h09; bad_addrs[7]  = 8'h0E;
        bad_addrs[8]  = 8'h0F; bad_addrs[9]  = 8'h10;
        bad_addrs[10] = 8'h14; bad_addrs[11] = 8'h1C;
        bad_addrs[12] = 8'h40; bad_addrs[13] = 8'h80;
        bad_addrs[14] = 8'hFC; bad_addrs[15] = 8'hFF;

        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;

        // 1. Reset: quiet outputs while in reset.
        repeat (3) begin
            @(negedge pclk);
            check_quiet;
        end
        @(negedge pclk);
        presetn = 1'b1;
        check_quiet;

        // 2. Reset values, back-to-back reads.
        read_all;
        idle(2);

        // 3. Full writes to every register back-to-back, then reads.
        apb_write(8'h00, 32'h1122_3344, 4'hF);
        apb_write(8'h04, 32'hA5A5_5A5A, 4'hF);
        apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
        apb_write(8'h0C, 32'h0123_4567, 4'hF);
        read_all;

        // 4. Write immediately followed by read of the same register.
        for (i = 0; i < 4; i = i + 1) begin
            apb_write({4'h0, i[1:0], 2'b00}, {4{i[3:0], ~i[3:0]}} ^ 32'hC3C3_3C3C, 4'hF);
            apb_read({4'h0, i[1:0], 2'b00});
        end

        // 5. Every strobe pattern (including none) on every register.
        for (r = 0; r < 4; r = r + 1) begin
            for (s = 0; s < 16; s = s + 1) begin
                apb_write({4'h0, r[1:0], 2'b00}, 32'hA5A5_A5A5, 4'hF);
                apb_write({4'h0, r[1:0], 2'b00}, 32'h5A5A_5A5A, s[3:0]);
                apb_read({4'h0, r[1:0], 2'b00});
                apb_write({4'h0, r[1:0], 2'b00}, 32'h0000_0000, 4'hF);
                apb_write({4'h0, r[1:0], 2'b00}, 32'hFFFF_FFFF, s[3:0]);
                apb_read({4'h0, r[1:0], 2'b00});
            end
        end

        // 6. Unmapped addresses: PSLVERR, no register change, zero read data.
        apb_write(8'h00, 32'h0BAD_0000, 4'hF);
        apb_write(8'h04, 32'h0BAD_0004, 4'hF);
        apb_write(8'h08, 32'h0BAD_0008, 4'hF);
        apb_write(8'h0C, 32'h0BAD_000C, 4'hF);
        for (i = 0; i < 16; i = i + 1) begin
            apb_write(bad_addrs[i[3:0]], 32'hFFFF_FFFF, 4'hF);
            apb_read(bad_addrs[i[3:0]]);
            apb_read({4'h0, i[1:0], 2'b00});
        end
        read_all;

        // 7. Idle gaps between transfers.
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF);
        idle(1);
        apb_read(8'h04);
        idle(3);
        apb_write(8'h0C, 32'h8765_4321, 4'h5);
        idle(2);
        apb_read(8'h0C);
        apb_read(8'h00);
        idle(1);
        apb_write(8'h11, 32'h1111_1111, 4'hF);
        idle(1);
        apb_read(8'h08);
        idle(2);

        // 8. Reset again: registers return to zero.
        apb_write(8'h00, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h04, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h08, 32'hFFFF_FFFF, 4'hF);
        apb_write(8'h0C, 32'hFFFF_FFFF, 4'hF);
        @(negedge pclk);
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b1;
        paddr   = 8'h00;
        pwdata  = 32'h1234_5678;
        pstrb   = 4'hF;
        model[0] = 32'h0000_0000;
        model[1] = 32'h0000_0000;
        model[2] = 32'h0000_0000;
        model[3] = 32'h0000_0000;
        check_quiet;
        repeat (2) begin
            @(negedge pclk);
            check_quiet;
        end
        @(negedge pclk);
        presetn = 1'b1;
        check_quiet;
        read_all;
        apb_write(8'h08, 32'h0F0F_0F0F, 4'h3);
        apb_read(8'h08);
        idle(1);

        done = 1'b1;
        finish_run;
    end

endmodule
`default_nettype wire
=== END FILE ===
